function SafeData({ loading, error, children, refetch }: { loading?: boolean; error?: boolean; children: ReactNode; refetch?: () => void }) { if (loading) return <LoadingBlock />; if (error) return <ErrorState onRetry={refetch} />; return <>{children}</>; }
function ShellPage({ children }: { children: ReactNode }) { return <AppShell>{children}</AppShell>; }
function Card({ children, className = '' }: { children: ReactNode; className?: string }) { return <div className={`rounded-2xl border border-border bg-card shadow-[0_5px_20px_hsl(226_40%_30%_/.035)] ${className}`}>{children}</div>; }
function SectionAction({ href, children = 'View all' }: { href: string; children?: React.ReactNode }) { return <Link href={href} className="inline-flex items-center gap-1 text-[11px] font-bold text-primary hover:gap-2" data-testid={`link-view-${href.slice(1)}`}>{children}<ArrowRight size={13} /></Link>; }
function timeAgo(timestamp: string) { const d = new Date(timestamp); if (Number.isNaN(d.valueOf())) return timestamp; const diff = Math.max(1, Math.round((Date.now() - d.valueOf()) / 60000)); return diff < 60 ? `${diff} min ago` : `${Math.round(diff / 60)} hr ago`; }

