export function DashboardPage() {
  const dashboard = useGetDashboard(); const activities = useGetActivities(); const docs = useGetDocuments(); const apps = useGetApplications(); const services = useGetServices();
  const summary = dashboard.data || fallbackDashboard; const documents = docs.data || fallbackDocs; const applications = apps.data || fallbackApps; const serviceList = services.data || fallbackServices; const activityList = activities.data || [];
  return <ShellPage><PageHeading eyebrow="Citizen workspace" title={`Good morning, ${summary.citizenName}.`} description="Here’s the clearest view of your public service progress today." action={<Link href="/govguide" className="inline-flex items-center gap-2 rounded-xl border border-border bg-card px-4 py-2.5 text-xs font-bold text-primary" data-testid="link-dashboard-govguide"><Sparkles size={14} /> Ask GovGuide</Link>} /><SafeData loading={dashboard.isLoading} error={!!dashboard.error} refetch={dashboard.refetch}><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Readiness score" value={`${summary.readinessScore}%`} detail="Strong foundation" icon={ShieldCheck} tint="bg-[#e7f5ef] text-[#25805a]" /><MetricCard label="Eligible services" value={summary.eligibleServices} detail="Ready to explore" icon={BriefcaseBusiness} /><MetricCard label="Active applications" value={summary.activeApplications} detail="One needs your eye" icon={FileCheck2} tint="bg-[#fff4d9] text-[#9c6c08]" /><MetricCard label="Time saved" value={`${summary.timeSavedMinutes} min`} detail="Since joining OneGovFlow" icon={Clock3} tint="bg-[#fff0e9] text-[#b95b35]" /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.5fr_1fr]"><Card className="overflow-hidden"><div className="flex items-center justify-between border-b border-border px-5 py-4"><SectionTitle title="Profile readiness" action={<SectionAction href="/profile">Complete profile</SectionAction>} /></div><div className="grid gap-6 p-5 sm:grid-cols-[.8fr_1.2fr] sm:items-center"><div className="relative mx-auto flex h-36 w-36 items-center justify-center rounded-full" style={{ background: `conic-gradient(#55a77b ${summary.readinessScore * 3.6}deg, #e6eaf2 0deg)` }}><div className="flex h-28 w-28 flex-col items-center justify-center rounded-full bg-card"><span className="font-display text-3xl font-extrabold">{summary.readinessScore}%</span><span className="text-[10px] text-muted-foreground">ready to apply</span></div></div><div><p className="text-sm font-bold">You’re in a good place, Aarav.</p><p className="mt-2 text-xs leading-5 text-muted-foreground">Add your address proof to unlock 2 more services and make your profile fully application-ready.</p><ProgressBar value={summary.profileCompletion || 82} color="bg-[#55a77b]" /><div className="mt-2 flex justify-between text-[10px] text-muted-foreground"><span>Profile completion</span><span>{summary.profileCompletion || 82}%</span></div><Link href="/documents" className="mt-5 inline-flex items-center gap-2 text-xs font-bold text-primary" data-testid="link-readiness-documents">Review documents <ArrowRight size={13} /></Link></div></div></Card><Card><div className="flex items-center justify-between border-b border-border px-5 py-4"><SectionTitle title="Quick actions" /></div><div className="grid grid-cols-2 gap-3 p-5">{[[FilePlus2,'Add a document','/documents'],[Search,'Find a service','/services'],[UserRound,'Update profile','/profile'],[MessageCircle,'Ask GovGuide','/govguide']].map(([Icon,label,href]) => <Link href={href as string} key={label as string} className="group rounded-xl border border-border p-3 hover:border-primary hover:bg-[#f8f9ff]" data-testid={`link-quick-${(label as string).replaceAll(' ','-').toLowerCase()}`}><span className="mb-3 block w-fit rounded-lg bg-secondary p-2 text-primary"><Icon size={15} /></span><p className="text-[11px] font-bold leading-4">{label as string}</p><ArrowRight size={13} className="mt-2 text-muted-foreground transition-transform group-hover:translate-x-1" /></Link>)}</div></Card></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.5fr_1fr]"><Card><div className="flex items-center justify-between border-b border-border px-5 py-4"><SectionTitle title="Applications in progress" action={<SectionAction href="/applications">View all</SectionAction>} /></div>{applications.slice(0,2).map((app) => <div key={app.id} className="border-b border-border p-5 last:border-0"><div className="flex items-start justify-between gap-3"><div className="flex items-center gap-3"><ServiceIcon accent={app.status === 'approved' ? 'mint' : 'indigo'} icon={FileCheck2} /><div><p className="text-sm font-bold">{app.serviceName}</p><p className="mt-1 font-mono-app text-[10px] text-muted-foreground">{app.reference}</p></div></div><StatusPill status={app.status} /></div><div className="mt-5"><div className="mb-2 flex justify-between text-[10px] text-muted-foreground"><span>Application progress</span><span className="font-bold text-foreground">{app.progress}%</span></div><ProgressBar value={app.progress} color={app.status === 'approved' ? 'bg-[#55a77b]' : 'bg-primary'} /></div></div>)}</Card><Card><div className="flex items-center justify-between border-b border-border px-5 py-4"><SectionTitle title="Recent activity" action={<SectionAction href="/applications">All activity</SectionAction>} /></div><div className="p-5">{activityList.length ? activityList.slice(0,5).map((item: Activity) => <div key={item.id} className="relative flex gap-3 pb-5 last:pb-0"><span className="relative z-10 mt-1 flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-secondary text-primary"><Check size={12} /></span><div><p className="text-[11px] font-bold">{item.title}</p><p className="mt-1 text-[10px] leading-4 text-muted-foreground">{item.description}</p><p className="mt-1 font-mono-app text-[9px] text-muted-foreground/70">{timeAgo(item.timestamp)}</p></div></div>) : <div className="py-5 text-center text-xs text-muted-foreground">Your activity will appear here as you move through services.</div>}</div></Card></div><div className="mt-6"><Card><div className="flex items-center justify-between border-b border-border px-5 py-4"><SectionTitle title="Services waiting for you" action={<SectionAction href="/services">Explore services</SectionAction>} /></div><div className="grid gap-3 p-5 md:grid-cols-3">{serviceList.filter((s) => s.status !== 'ineligible').slice(0,3).map((service) => <Link href="/services" key={service.id} className="flex items-center gap-3 rounded-xl border border-border p-3 hover:border-primary" data-testid={`card-dashboard-service-${service.id}`}><ServiceIcon accent={service.accent} icon={service.category === 'Education' ? BookOpen : service.category === 'Identity' ? UserRound : Landmark} /><div className="min-w-0"><p className="truncate text-xs font-bold">{service.name}</p><p className="mt-1 text-[10px] text-muted-foreground">{service.processingTime}</p></div><ArrowRight size={14} className="ml-auto shrink-0 text-muted-foreground" /></Link>)}</div></Card></div><div className="sr-only">{documents.length}</div></SafeData></ShellPage>;
}

export function ProfilePage() {
  const profile = useGetProfile(); const update = useUpdateProfile(); const [saved, setSaved] = useState(false); const p = profile.data; const [form, setForm] = useState<Partial<CitizenProfile>>({});
  const value = (key: keyof CitizenProfile) => form[key] ?? p?.[key] ?? '';
  const set = (key: keyof CitizenProfile, val: string | number) => setForm((old) => ({ ...old, [key]: val }));
  const save = (e: FormEvent) => { e.preventDefault(); update.mutate({ data: { ...form, age: Number(form.age ?? p?.age ?? 0), annualIncome: Number(form.annualIncome ?? p?.annualIncome ?? 0) } }, { onSuccess: () => setSaved(true) }); };
  return <ShellPage><PageHeading eyebrow="Your identity" title="My profile" description="Keep these details current once, and use them across every application." action={<div className="flex items-center gap-3">{saved && <span className="flex items-center gap-1.5 text-xs font-bold text-[#25805a]"><CheckCircle2 size={15} /> Saved just now</span>}<PrimaryButton type="submit" onClick={() => (document.getElementById('profile-form') as HTMLFormElement | null)?.requestSubmit()} disabled={update.isPending}>{update.isPending ? 'Saving…' : 'Save changes'}</PrimaryButton></div>} /><SafeData loading={profile.isLoading} error={!!profile.error} refetch={profile.refetch}><form id="profile-form" onSubmit={save} className="grid gap-6 xl:grid-cols-[1fr_280px]"><div className="space-y-6"><Card><div className="border-b border-border px-6 py-5"><SectionTitle title="Basic information" /><p className="text-xs text-muted-foreground">This is how departments will identify you.</p></div><div className="grid gap-5 p-6 sm:grid-cols-2"><Field label="Full name" value={value('fullName')} onChange={(v) => set('fullName', v)} test="input-profile-name" /><Field label="Mobile number" value={value('mobile')} onChange={(v) => set('mobile', v)} test="input-profile-mobile" /><Field label="Email address" value={value('email')} onChange={(v) => set('email', v)} test="input-profile-email" disabled /><Field label="Aadhaar number" value={value('aadhaarMasked')} onChange={() => {}} test="input-profile-aadhaar" disabled /></div></Card><Card><div className="border-b border-border px-6 py-5"><SectionTitle title="About you" /><p className="text-xs text-muted-foreground">A few details help us explain your eligibility accurately.</p></div><div className="grid gap-5 p-6 sm:grid-cols-2"><Field label="Age" value={value('age')} onChange={(v) => set('age', v)} test="input-profile-age" type="number" /><Field label="Gender" value={value('gender')} onChange={(v) => set('gender', v)} test="input-profile-gender" /><Field label="Education" value={value('education')} onChange={(v) => set('education', v)} test="input-profile-education" /><Field label="Occupation" value={value('occupation')} onChange={(v) => set('occupation', v)} test="input-profile-occupation" /><Field label="Annual income" value={value('annualIncome')} onChange={(v) => set('annualIncome', v)} test="input-profile-income" type="number" /><Field label="Social category" value={value('socialCategory')} onChange={(v) => set('socialCategory', v)} test="input-profile-category" /></div></Card><Card><div className="border-b border-border px-6 py-5"><SectionTitle title="Location" /><p className="text-xs text-muted-foreground">Used to show the services available in your area.</p></div><div className="grid gap-5 p-6 sm:grid-cols-3"><Field label="State" value={value('state')} onChange={(v) => set('state', v)} test="input-profile-state" /><Field label="District" value={value('district')} onChange={(v) => set('district', v)} test="input-profile-district" /><Field label="Village / town" value={value('village')} onChange={(v) => set('village', v)} test="input-profile-village" /></div></Card></div><Card className="h-fit p-5"><div className="flex items-center gap-3"><div className="flex h-12 w-12 items-center justify-center rounded-full bg-[#e3ad3f] font-bold text-[#262b52]">AS</div><div><p className="font-display font-extrabold">{p?.fullName || 'Aarav Sharma'}</p><p className="text-[11px] text-muted-foreground">Citizen ID · {p?.id || 'OGF-240618'}</p></div></div><div className="my-5 border-t border-border pt-5"><div className="mb-2 flex justify-between text-[10px] font-bold"><span>Profile completion</span><span className="text-primary">{p?.completion || 82}%</span></div><ProgressBar value={p?.completion || 82} color="bg-[#55a77b]" /><p className="mt-3 text-[11px] leading-5 text-muted-foreground">Complete profiles receive more accurate recommendations.</p></div><div className="flex items-center gap-2 rounded-xl bg-[#e7f5ef] p-3 text-[11px] font-bold text-[#23794e]"><ShieldCheck size={15} /> Identity details protected</div></Card></form></SafeData></ShellPage>;
}

function Field({ label, value, onChange, test, type = 'text', disabled = false }: { label: string; value: unknown; onChange: (value: string) => void; test: string; type?: string; disabled?: boolean }) { return <label className="block text-xs font-bold text-foreground">{label}<input type={type} value={String(value)} onChange={(e) => onChange(e.target.value)} disabled={disabled} className="mt-2 h-11 w-full rounded-xl border border-input bg-background px-3 text-sm font-normal outline-none transition-colors focus:border-primary disabled:cursor-not-allowed disabled:opacity-60" data-testid={test} /></label>; }

export function DocumentsPage() {
  const docs = useGetDocuments(); const create = useCreateDocument(); const [showAdd, setShowAdd] = useState(false); const [name, setName] = useState(''); const [category, setCategory] = useState('Identity'); const list = docs.data || fallbackDocs;
  const add = (e: FormEvent) => { e.preventDefault(); if (!name) return; create.mutate({ data: { name, category, size: 'Pending upload' } }, { onSuccess: () => { setName(''); setShowAdd(false); } }); };
  return <ShellPage><PageHeading eyebrow="Your digital locker" title="Document vault" description="One secure place for the documents you use most often." action={<PrimaryButton onClick={() => setShowAdd(!showAdd)}><Plus size={15} /> Add document</PrimaryButton>} /><SafeData loading={docs.isLoading} error={!!docs.error} refetch={docs.refetch}><Card className="mb-6 overflow-hidden bg-[#2f3c88] text-white"><div className="grid items-center gap-6 p-6 sm:grid-cols-[1fr_auto] sm:p-8"><div><p className="text-[10px] font-bold uppercase tracking-[.16em] text-[#e7bb55]">Vault status</p><h2 className="mt-2 font-display text-2xl font-extrabold">Your essentials are almost ready.</h2><p className="mt-2 max-w-md text-xs leading-5 text-[#c3c9e2]">Add and verify documents once. OneGovFlow will tell you exactly where each one can be used.</p></div><div className="flex items-center gap-4"><div className="flex h-20 w-20 items-center justify-center rounded-full border-[7px] border-[#55a77b] font-display text-xl font-extrabold">75%</div><div className="text-[11px] text-[#c3c9e2]"><p className="font-bold text-white">{list.filter((d) => d.verified).length} verified</p><p className="mt-1">of {list.length} documents</p></div></div></div></Card>{showAdd && <form onSubmit={add} className="mb-6 rounded-2xl border border-primary/30 bg-[#f8f9ff] p-5"><div className="mb-4 flex items-center justify-between"><div><p className="font-display font-extrabold">Add document details</p><p className="mt-1 text-xs text-muted-foreground">You can attach the file after saving the record.</p></div><button type="button" onClick={() => setShowAdd(false)} className="text-xs font-bold text-muted-foreground" data-testid="button-cancel-document">Cancel</button></div><div className="grid gap-4 sm:grid-cols-[1fr_200px_auto] sm:items-end"><Field label="Document name" value={name} onChange={setName} test="input-document-name" /><label className="block text-xs font-bold">Category<select value={category} onChange={(e) => setCategory(e.target.value)} className="mt-2 h-11 w-full rounded-xl border border-input bg-card px-3 text-xs outline-none" data-testid="select-document-category"><option>Identity</option><option>Income</option><option>Education</option><option>Address</option><option>Other</option></select></label><PrimaryButton type="submit" disabled={create.isPending}>{create.isPending ? 'Adding…' : 'Add to vault'}</PrimaryButton></div></form>}<div className="grid gap-6 lg:grid-cols-[1fr_300px]"><Card><div className="flex items-center justify-between border-b border-border px-5 py-4"><SectionTitle title={`All documents · ${list.length}`} action={<button onClick={() => setShowAdd(!showAdd)} className="flex items-center gap-1 text-[11px] font-bold text-muted-foreground" data-testid="button-filter-documents"><Filter size={13} /> Filter</button>} /></div>{list.length ? list.map((doc) => <div key={doc.id} className="flex flex-col gap-4 border-b border-border p-5 last:border-0 sm:flex-row sm:items-center"><div className="flex min-w-0 items-center gap-3"><span className="rounded-xl bg-secondary p-2.5 text-primary"><FileText size={18} /></span><div className="min-w-0"><p className="truncate text-sm font-bold">{doc.name}</p><p className="mt-1 text-[10px] text-muted-foreground">{doc.category} · {doc.size} · Updated {doc.updatedAt}</p></div></div><div className="ml-auto flex items-center gap-4"><StatusPill status={doc.status} /><button onClick={() => setShowAdd(true)} className="rounded-lg p-2 text-muted-foreground hover:bg-secondary" aria-label={`Edit ${doc.name}`} data-testid={`button-edit-document-${doc.id}`}><Pencil size={14} /></button></div></div>) : <EmptyState title="Your vault is waiting" description="Add your first document to make future applications faster." action={<PrimaryButton className="mt-4" onClick={() => setShowAdd(true)}><Plus size={14} /> Add document</PrimaryButton>} />}</Card><Card className="h-fit p-5"><SectionTitle title="How verification works" /><div className="space-y-5">{[['1','Add details','Tell us what the document is.'],['2','Upload safely','Attach a clear copy when ready.'],['3','Use with confidence','We show where it can help.']].map(([n,t,d]) => <div key={n} className="flex gap-3"><span className="font-mono-app text-xs font-bold text-[#e1ad42]">{n}</span><div><p className="text-xs font-bold">{t}</p><p className="mt-1 text-[10px] leading-4 text-muted-foreground">{d}</p></div></div>)}</div><div className="mt-6 flex items-center gap-2 border-t border-border pt-4 text-[10px] font-bold text-[#23794e]"><ShieldCheck size={14} /> Documents are private by default</div></Card></div></SafeData></ShellPage>;
}

export function ServicesPage() {
  const [search, setSearch] = useState(''); const [category, setCategory] = useState('All'); const services = useGetServices({ search: search || undefined, category: category === 'All' ? undefined : category }); const apps = useCreateApplication(); const [applied, setApplied] = useState<string | null>(null); const list = services.data || fallbackServices; const categories = ['All', ...Array.from(new Set(fallbackServices.map((s) => s.category)))]; const filtered = useMemo(() => list.filter((s) => (!search || `${s.name} ${s.description}`.toLowerCase().includes(search.toLowerCase())) && (category === 'All' || s.category === category)), [list, search, category]);
  return <ShellPage><PageHeading eyebrow="Public services" title="Find your next service" description="Explore services matched to your profile, without the government-office guesswork." /><div className="mb-6 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" size={17} /><input value={search} onChange={(e) => setSearch(e.target.value)} className="h-12 w-full rounded-xl border border-input bg-card pl-10 pr-4 text-sm outline-none focus:border-primary" placeholder="Search scholarships, certificates, identity..." data-testid="input-service-search" /></div><div className="flex gap-2 overflow-x-auto">{categories.map((item) => <button key={item} onClick={() => setCategory(item)} className={`whitespace-nowrap rounded-xl px-4 text-xs font-bold ${category === item ? 'bg-primary text-primary-foreground' : 'border border-border bg-card text-muted-foreground'}`} data-testid={`button-category-${item.toLowerCase()}`}>{item}</button>)}</div></div><SafeData loading={services.isLoading} error={!!services.error} refetch={services.refetch}><div className="grid gap-4 lg:grid-cols-2">{filtered.length ? filtered.map((service) => <ServiceCard key={service.id} service={service} applied={applied === service.id} onApply={() => { apps.mutate({ data: { serviceId: service.id } }, { onSuccess: () => setApplied(service.id) }); }} loading={apps.isPending} />) : <div className="lg:col-span-2"><EmptyState title="No services match that search" description="Try a broader search or choose another category." action={<button onClick={() => { setSearch(''); setCategory('All'); }} className="mt-4 text-xs font-bold text-primary" data-testid="button-clear-service-filter">Clear filters</button>} /></div>}</div></SafeData></ShellPage>;
}
function ServiceCard({ service, onApply, applied, loading }: { service: GovernmentService; onApply: () => void; applied: boolean; loading: boolean }) { const [, setLocation] = useLocation(); const icon = service.category === 'Education' ? BookOpen : service.category === 'Identity' ? UserRound : service.category === 'Welfare' ? WalletCards : Landmark; return <Card className="group flex flex-col p-5 transition-transform hover:-translate-y-0.5"><div className="flex items-start gap-4"><ServiceIcon accent={service.accent} icon={icon} /><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><div><p className="font-display text-lg font-extrabold tracking-[-.02em]">{service.name}</p><p className="mt-1 text-[10px] font-bold uppercase tracking-[.1em] text-muted-foreground">{service.category}</p></div><StatusPill status={service.status} /></div><p className="mt-4 text-xs leading-5 text-muted-foreground">{service.description}</p></div></div><div className="mt-5 border-t border-border pt-4"><div className="flex items-center gap-4 text-[10px] text-muted-foreground"><span className="flex items-center gap-1"><Clock3 size={13} /> {service.processingTime}</span><span className="flex items-center gap-1"><FileText size={13} /> {service.requiredDocuments.length} documents</span></div><p className="mt-3 text-[11px] font-semibold text-foreground">{service.reason}</p><div className="mt-5 flex items-center justify-between"><button onClick={() => service.status === 'eligible' ? onApply() : setLocation('/eligibility')} disabled={loading || applied} className="rounded-xl bg-primary px-4 py-2.5 text-[11px] font-bold text-primary-foreground disabled:cursor-not-allowed disabled:bg-secondary disabled:text-muted-foreground" data-testid={`button-apply-${service.id}`}>{applied ? 'Application started' : service.status === 'eligible' ? (loading ? 'Starting…' : 'Start application') : 'View requirements'}</button><Link href="/eligibility" className="text-[11px] font-bold text-primary" data-testid={`link-service-eligibility-${service.id}`}>Why this result <ArrowRight className="ml-1 inline" size={12} /></Link></div></div></Card>; }

export function EligibilityPage() {
  const eligibility = useGetEligibility(); const results = eligibility.data || fallbackEligibility; const [expanded, setExpanded] = useState<string | null>(null);
  return <ShellPage><PageHeading eyebrow="Your eligibility" title="Recommendations, explained" description="We show the reason behind every result — not just a green or red label." action={<Link href="/profile" className="inline-flex items-center gap-2 rounded-xl border border-border bg-card px-4 py-2.5 text-xs font-bold text-primary" data-testid="link-eligibility-profile"><Pencil size={13} /> Update profile</Link>} /><SafeData loading={eligibility.isLoading} error={!!eligibility.error} refetch={eligibility.refetch}><Card className="mb-6 overflow-hidden"><div className="grid gap-0 md:grid-cols-[.8fr_1.2fr]"><div className="bg-[#2f3c88] p-6 text-white sm:p-8"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#ffffff18] text-[#e7bb55]"><Sparkles size={20} /></span><h2 className="mt-7 font-display text-2xl font-extrabold tracking-[-.035em]">A clearer yes.</h2><p className="mt-3 text-xs leading-5 text-[#c3c9e2]">Your recommendations are based on your profile, location and verified documents. Keep them current for better matches.</p></div><div className="grid grid-cols-3 items-center gap-3 p-6 sm:p-8"><div><p className="font-display text-3xl font-extrabold text-[#25805a]">{results.filter((r) => r.status === 'eligible').length}</p><p className="mt-1 text-[10px] text-muted-foreground">Ready now</p></div><div><p className="font-display text-3xl font-extrabold text-[#9b6a00]">{results.filter((r) => r.status === 'needs-action').length}</p><p className="mt-1 text-[10px] text-muted-foreground">Need one step</p></div><div><p className="font-display text-3xl font-extrabold text-muted-foreground">{results.filter((r) => r.status === 'ineligible').length}</p><p className="mt-1 text-[10px] text-muted-foreground">Not a match</p></div></div></div></Card><div className="space-y-3">{results.map((result) => <Card key={result.serviceId} className="overflow-hidden"><button onClick={() => setExpanded(expanded === result.serviceId ? null : result.serviceId)} className="flex w-full items-center gap-4 p-5 text-left" data-testid={`button-expand-eligibility-${result.serviceId}`}><div className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl ${result.status === 'eligible' ? 'bg-[#e7f5ef] text-[#25805a]' : result.status === 'needs-action' ? 'bg-[#fff4d9] text-[#9c6c08]' : 'bg-secondary text-muted-foreground'}`}>{result.status === 'eligible' ? <CheckCircle2 size={19} /> : result.status === 'needs-action' ? <ArrowDownRight size={19} /> : <BriefcaseBusiness size={19} />}</div><div className="min-w-0 flex-1"><p className="text-sm font-bold">{result.serviceName}</p><p className="mt-1 text-xs text-muted-foreground">{result.reason}</p></div><StatusPill status={result.status} /><ArrowRight size={15} className={`text-muted-foreground transition-transform ${expanded === result.serviceId ? 'rotate-90' : ''}`} /></button>{expanded === result.serviceId && <div className="border-t border-border bg-background px-5 py-5 sm:pl-[76px]"><p className="text-[10px] font-bold uppercase tracking-[.15em] text-muted-foreground">What informed this result</p><p className="mt-2 text-xs leading-5 text-muted-foreground">{result.reason} We looked at your profile details and the documents available in your vault.</p>{result.missingDocuments.length > 0 && <div className="mt-4 rounded-xl bg-[#fff8e8] p-3 text-xs"><p className="font-bold text-[#9b6a00]">To become eligible</p><p className="mt-1 text-[#876a2b]">Add: {result.missingDocuments.join(', ')}</p><Link href="/documents" className="mt-3 inline-flex items-center gap-1 font-bold text-primary" data-testid={`link-add-missing-${result.serviceId}`}>Go to document vault <ArrowRight size={13} /></Link></div>}{result.status === 'eligible' && <Link href="/services" className="mt-4 inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-[11px] font-bold text-primary-foreground" data-testid={`link-start-eligible-${result.serviceId}`}>Start application <ArrowRight size={13} /></Link>}</div>}</Card>)}</div></SafeData></ShellPage>;
}

export function ApplicationsPage() {
  const applications = useGetApplications(); const list = applications.data || fallbackApps; const [selected, setSelected] = useState(list[0]?.id); const current = list.find((a) => a.id === selected) || list[0];
  return <ShellPage><PageHeading eyebrow="Your progress" title="Applications" description="Every submission, milestone and next step — in one calm view." action={<Link href="/services" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-xs font-bold text-primary-foreground" data-testid="link-new-application"><Plus size={14} /> New application</Link>} /><SafeData loading={applications.isLoading} error={!!applications.error} refetch={applications.refetch}>{list.length ? <div className="grid gap-6 xl:grid-cols-[.85fr_1.15fr]"><Card className="h-fit overflow-hidden"><div className="border-b border-border px-5 py-4"><SectionTitle title="All applications" /></div>{list.map((app) => <button key={app.id} onClick={() => setSelected(app.id)} className={`flex w-full items-start gap-3 border-b border-border p-5 text-left last:border-0 ${selected === app.id ? 'bg-[#f5f7ff]' : 'hover:bg-background'}`} data-testid={`button-select-application-${app.id}`}><span className={`mt-0.5 rounded-xl p-2.5 ${app.status === 'approved' ? 'bg-[#e7f5ef] text-[#25805a]' : 'bg-secondary text-primary'}`}><FileCheck2 size={17} /></span><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><p className="truncate text-xs font-bold">{app.serviceName}</p><StatusPill status={app.status} /></div><p className="mt-2 font-mono-app text-[9px] text-muted-foreground">{app.reference}</p><div className="mt-3"><ProgressBar value={app.progress} color={app.status === 'approved' ? 'bg-[#55a77b]' : 'bg-primary'} /></div></div></button>)}</Card>{current && <Card><div className="border-b border-border p-6"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-[10px] font-bold uppercase tracking-[.16em] text-primary">Application detail</p><h2 className="mt-2 font-display text-2xl font-extrabold tracking-[-.03em]">{current.serviceName}</h2><p className="mt-2 font-mono-app text-[10px] text-muted-foreground">{current.reference} · Updated {current.updatedAt}</p></div><StatusPill status={current.status} /></div><div className="mt-7"><div className="mb-2 flex justify-between text-[11px] font-bold"><span>Overall progress</span><span>{current.progress}%</span></div><ProgressBar value={current.progress} color={current.status === 'approved' ? 'bg-[#55a77b]' : 'bg-primary'} /></div></div><div className="p-6"><p className="mb-6 text-[10px] font-bold uppercase tracking-[.16em] text-muted-foreground">Application timeline</p><ApplicationStepper steps={current.steps} /><div className="mt-8 rounded-xl bg-background p-4"><div className="flex gap-3"><span className="rounded-lg bg-[#fff4d9] p-2 text-[#9b6a00]"><Clock3 size={16} /></span><div><p className="text-xs font-bold">{current.status === 'approved' ? 'Application approved' : 'Officer review is in progress'}</p><p className="mt-1 text-[11px] leading-5 text-muted-foreground">{current.status === 'approved' ? 'Your decision is ready. Keep your reference number for future use.' : 'No action is needed from you right now. We’ll let you know when there is an update.'}</p></div></div></div><button className="mt-5 inline-flex items-center gap-2 text-[11px] font-bold text-primary" data-testid="button-copy-reference" onClick={() => navigator.clipboard?.writeText(current.reference)}><Copy size={13} /> Copy reference number</button></div></Card>}</div> : <EmptyState title="No applications yet" description="When you find a service that fits, your application journey will live here." action={<Link href="/services" className="mt-4 rounded-xl bg-primary px-4 py-2.5 text-xs font-bold text-primary-foreground" data-testid="link-empty-browse-services">Browse services</Link>} />}</SafeData></ShellPage>;
}

export function GovGuidePage() {
  const demo = useRunJudgeDemo(); const [started, setStarted] = useState(false); const [message, setMessage] = useState('I can help you find a service, understand a requirement, or prepare your next application.'); const run = () => { setStarted(true); demo.mutate(undefined, { onSuccess: (state) => setMessage(state.message) }); };
  return <ShellPage><PageHeading eyebrow="Your service desk" title="GovGuide" description="A guided assistant for the parts of public services that usually feel unclear." /><div className="grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><Card className="overflow-hidden"><div className="border-b border-border bg-[#2f3c88] p-6 text-white sm:p-8"><div className="flex items-center gap-3"><span className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#e7bb55] text-[#2f3c88]"><Sparkles size={22} /></span><div><p className="font-display text-xl font-extrabold">GovGuide assistant</p><p className="mt-1 text-[11px] text-[#c3c9e2]">Plain answers. Clear next steps.</p></div></div></div><div className="p-6 sm:p-8"><div className="max-w-xl rounded-2xl rounded-tl-sm bg-background p-5 text-sm leading-6 text-foreground">{message}</div><div className="mt-6 grid gap-3 sm:grid-cols-2"><button onClick={() => setMessage('Based on your profile, Asha Scholarship is your strongest next step. You have the required identity, income and education documents ready.')} className="rounded-xl border border-border p-4 text-left text-xs font-bold hover:border-primary" data-testid="button-guide-scholarship"><BookOpen size={16} className="mb-3 text-primary" />Find education support<span className="mt-2 block text-[10px] font-normal text-muted-foreground">See scholarships you may qualify for</span></button><button onClick={() => setMessage('Your profile is 82% complete. Adding a verified address proof will unlock domicile services and improve your recommendations.')} className="rounded-xl border border-border p-4 text-left text-xs font-bold hover:border-primary" data-testid="button-guide-profile"><UserRound size={16} className="mb-3 text-primary" />Check my readiness<span className="mt-2 block text-[10px] font-normal text-muted-foreground">Know what to do next</span></button></div></div></Card><Card className="h-fit p-6"><p className="text-[10px] font-bold uppercase tracking-[.16em] text-primary">Judge Demo Mode</p><h2 className="mt-3 font-display text-xl font-extrabold">Watch a service journey come together.</h2><p className="mt-2 text-xs leading-5 text-muted-foreground">Run the guided flow to see how OneGovFlow moves a citizen from profile to a submitted application.</p><div className="mt-6 space-y-4">{['Profile understood','Eligibility checked','Application prepared','Ready to submit'].map((step, index) => <div key={step} className="flex items-center gap-3"><span className={`flex h-7 w-7 items-center justify-center rounded-full text-[11px] font-bold ${started && index <= 1 ? 'bg-[#55a77b] text-white' : 'bg-secondary text-muted-foreground'}`}>{started && index <= 1 ? <Check size={14} /> : index + 1}</span><p className={`text-xs font-bold ${started && index <= 1 ? 'text-foreground' : 'text-muted-foreground'}`}>{step}</p></div>)}</div><PrimaryButton className="mt-7 w-full" onClick={run} disabled={demo.isPending}>{demo.isPending ? 'Running guided demo…' : started ? 'Run again' : 'Run demo mode'} <ArrowRight size={14} /></PrimaryButton></Card></div></ShellPage>;
}

export function AdminPage() {
  const overview = useGetAdminOverview(); const data = overview.data; const fallback = { pendingReview: 18, verificationRequests: 7, approvedToday: 24, averageProcessingTime: '2.4 days', queue: [{ id: '1', applicant: 'Aarav Sharma', serviceName: 'Asha Scholarship', priority: 'high', submittedAt: 'Today, 09:42' }, { id: '2', applicant: 'Meera Iyer', serviceName: 'Domicile certificate', priority: 'medium', submittedAt: 'Today, 09:18' }, { id: '3', applicant: 'Kabir Khan', serviceName: 'New PAN card', priority: 'low', submittedAt: 'Yesterday, 17:05' }] }; const d = data || fallback;
  return <ShellPage><PageHeading eyebrow="Officer workspace" title="Good morning, officer." description="A focused view of today’s review queue and service throughput." action={<span className="flex items-center gap-2 rounded-full bg-[#e7f5ef] px-3 py-2 text-[10px] font-bold text-[#23794e]"><span className="h-1.5 w-1.5 rounded-full bg-current" /> System operational</span>} /><SafeData loading={overview.isLoading} error={!!overview.error} refetch={overview.refetch}><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Pending review" value={d.pendingReview} detail="Requires attention" icon={Clock3} tint="bg-[#fff4d9] text-[#9c6c08]" /><MetricCard label="Verification requests" value={d.verificationRequests} detail="Document checks" icon={ShieldCheck} /><MetricCard label="Approved today" value={d.approvedToday} detail="Across all services" icon={CheckCircle2} tint="bg-[#e7f5ef] text-[#25805a]" /><MetricCard label="Avg. processing time" value={d.averageProcessingTime} detail="Down 0.6 days this week" icon={ArrowDownRight} tint="bg-[#fff0e9] text-[#b95b35]" /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.35fr_.65fr]"><Card><div className="flex items-center justify-between border-b border-border px-5 py-4"><SectionTitle title="Review queue" action={<button className="flex items-center gap-1 text-[11px] font-bold text-primary" data-testid="button-export-queue">Export queue <ArrowRight size={13} /></button>} /></div><div className="hidden grid-cols-[1.2fr_1fr_.7fr_1fr] gap-3 border-b border-border bg-background px-5 py-3 text-[9px] font-bold uppercase tracking-[.12em] text-muted-foreground sm:grid"><span>Applicant</span><span>Service</span><span>Priority</span><span>Submitted</span></div>{d.queue.map((item) => <div key={item.id} className="grid gap-2 border-b border-border px-5 py-4 last:border-0 sm:grid-cols-[1.2fr_1fr_.7fr_1fr] sm:items-center sm:gap-3"><div><p className="text-xs font-bold">{item.applicant}</p><p className="mt-1 font-mono-app text-[9px] text-muted-foreground">{item.id}</p></div><p className="text-xs text-muted-foreground">{item.serviceName}</p><span className={`w-fit rounded-full px-2 py-1 text-[9px] font-bold uppercase ${item.priority === 'high' ? 'bg-[#fcebea] text-[#ae403b]' : item.priority === 'medium' ? 'bg-[#fff4d9] text-[#9b6a00]' : 'bg-secondary text-muted-foreground'}`}>{item.priority}</span><p className="text-[10px] text-muted-foreground">{item.submittedAt}</p></div>)}</Card><Card className="h-fit p-5"><SectionTitle title="Today at a glance" /><div className="surface-grid rounded-xl p-5"><p className="font-display text-4xl font-extrabold tracking-[-.05em] text-primary">84%</p><p className="mt-2 text-xs font-bold">Queue on track</p><p className="mt-1 text-[10px] leading-4 text-muted-foreground">Most applications are moving within the expected window.</p><ProgressBar value={84} color="bg-[#55a77b]" /></div><div className="mt-5 space-y-3 text-xs"><div className="flex justify-between"><span className="text-muted-foreground">Document verifications</span><b>31 completed</b></div><div className="flex justify-between"><span className="text-muted-foreground">Citizen questions</span><b>12 answered</b></div></div></Card></div></SafeData></ShellPage>;
}

export function SettingsPage() {
  const [saved, setSaved] = useState(false);
  const [email, setEmail] = useState(true);
  const [sms, setSms] = useState(false);
  const { language, setLanguage, translate } = useLanguage();
  const notifications = [
    ['Application updates', 'Know when a department moves your application.', email],
    ['Document verification', 'Get notified when a document is verified.', sms],
    ['Service recommendations', 'Hear about services matched to your profile.', true],
  ] as const;

  return <ShellPage>
    <PageHeading eyebrow={translate('Account')} title={translate('Settings')} description={translate('Choose how OneGovFlow keeps you informed and connected.')} action={saved ? <span className="flex items-center gap-1.5 text-xs font-bold text-[#25805a]"><CheckCircle2 size={15} /> {translate('Preferences saved')}</span> : undefined} />
    <div className="grid gap-6 lg:grid-cols-[1fr_300px]">
      <div className="space-y-6">
        <Card>
          <div className="border-b border-border px-6 py-5"><SectionTitle title={translate('Language')} /><p className="text-xs text-muted-foreground">{translate('Change language anytime from here.')}</p></div>
          <div className="grid gap-3 p-6 sm:grid-cols-2">
            {(['en', 'hi'] as const).map((option) => <button key={option} type="button" onClick={() => setLanguage(option)} className={`flex items-center justify-between rounded-xl border-2 px-4 py-4 text-left transition ${language === option ? 'border-primary bg-[#f5f7ff]' : 'border-border bg-card hover:border-primary/50'}`} data-testid={`button-settings-language-${option}`}>
              <span><span className="block text-sm font-bold">{option === 'en' ? 'English' : 'हिन्दी'}</span><span className="mt-1 block text-[10px] text-muted-foreground">{option === 'en' ? 'English' : 'Hindi'}</span></span>
              {language === option && <CheckCircle2 size={18} className="text-primary" />}
            </button>)}
          </div>
          <p className="px-6 pb-6 text-[11px] text-[#25805a]">{translate('Language preference saved')}</p>
        </Card>
        <Card>
          <div className="border-b border-border px-6 py-5"><SectionTitle title={translate('Notifications')} /><p className="text-xs text-muted-foreground">{translate('Useful updates, never noise.')}</p></div>
          <div className="divide-y divide-border">{notifications.map(([title, description, on]) => <div key={title} className="flex items-center justify-between gap-4 px-6 py-5"><div><p className="text-sm font-bold">{translate(title)}</p><p className="mt-1 text-xs text-muted-foreground">{translate(description)}</p></div><button onClick={() => title === 'Application updates' ? setEmail(!email) : title === 'Document verification' ? setSms(!sms) : undefined} className={`relative h-6 w-11 rounded-full transition-colors ${on ? 'bg-primary' : 'bg-secondary'}`} aria-label={`Toggle ${title}`} data-testid={`button-toggle-${title.replaceAll(' ', '-').toLowerCase()}`}><span className={`absolute top-1 h-4 w-4 rounded-full bg-white transition-transform ${on ? 'translate-x-6' : 'translate-x-1'}`} /></button></div>)}</div>
        </Card>
        <Card>
          <div className="border-b border-border px-6 py-5"><SectionTitle title={translate('Security & privacy')} /></div>
          <div className="divide-y divide-border">
            <button className="flex w-full items-center justify-between px-6 py-5 text-left hover:bg-background" data-testid="button-manage-consent"><div><p className="text-sm font-bold">{translate('Manage data consent')}</p><p className="mt-1 text-xs text-muted-foreground">{translate('Review what you have chosen to share.')}</p></div><ArrowRight size={15} className="text-muted-foreground" /></button>
            <button className="flex w-full items-center justify-between px-6 py-5 text-left hover:bg-background" data-testid="button-download-data"><div><p className="text-sm font-bold">{translate('Download my data')}</p><p className="mt-1 text-xs text-muted-foreground">{translate('Get a copy of your OneGovFlow information.')}</p></div><ArrowRight size={15} className="text-muted-foreground" /></button>
          </div>
        </Card>
        <PrimaryButton onClick={() => setSaved(true)}><Check size={14} /> {translate('Save preferences')}</PrimaryButton>
      </div>
      <Card className="h-fit p-5"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#e7f5ef] text-[#25805a]"><ShieldCheck size={19} /></span><h3 className="mt-5 font-display text-lg font-extrabold">{translate('Your account is protected')}</h3><p className="mt-2 text-xs leading-5 text-muted-foreground">{translate('We only use your information to help you access public services. You can change your choices at any time.')}</p><Link href="/govguide" className="mt-5 inline-flex items-center gap-2 text-[11px] font-bold text-primary" data-testid="link-settings-help">Have a question? Ask GovGuide <ArrowRight size={13} /></Link></Card>
    </div>
  </ShellPage>;
}